package fleetflow;
import java.util.*;
public class Module3 {
 public static void menu(Scanner sc){while(true){System.out.println("\n--- MODULE 3: DYNAMIC PROGRAMMING ---\n1. Levenshtein edit distance\n2. Matrix-chain multiplication\n3. TSP bitmask DP (up to 12 cities)\n4. 0/1 Knapsack\n0. Back");int c=Util.readInt(sc,"Choice: ");if(c==0)return;switch(c){case 1:String a=Util.readLine(sc,"String A: "),b=Util.readLine(sc,"String B: ");System.out.println("Edit distance = "+Module2.editDistance(a,b));break;case 2:int n=Util.readInt(sc,"Number of matrices: ");if(n<1||n>30){System.out.println("Use 1..30 matrices.");break;}int[]p=new int[n+1];for(int i=0;i<=n;i++)p[i]=Util.readInt(sc,"Dimension p["+i+"]: ");System.out.println("Minimum scalar multiplications = "+matrixChain(p));break;case 3:int k=Util.readInt(sc,"Number of cities (2..12): ");if(k<2||k>12){System.out.println("Use 2..12 cities.");break;}int[][]g=new int[k][k];System.out.println("Enter distance matrix row by row; use 0 on diagonal:");for(int i=0;i<k;i++)for(int j=0;j<k;j++)g[i][j]=Util.readInt(sc,"d["+i+"]["+j+"]: ");System.out.println("Minimum tour cost starting at city 0 = "+tsp(g));break;case 4:int m=Util.readInt(sc,"Number of items: ");int[]w=new int[m],v=new int[m];for(int i=0;i<m;i++){w[i]=Util.readInt(sc,"Weight "+i+": ");v[i]=Util.readInt(sc,"Value "+i+": ");}int cap=Util.readInt(sc,"Capacity: ");System.out.println("Maximum value = "+knapsack(w,v,cap));break;default:System.out.println("Invalid choice.");}}}
 public static long matrixChain(int[]p){int n=p.length-1;long[][]d=new long[n][n];for(int len=2;len<=n;len++)for(int i=0;i+len<=n;i++){int j=i+len-1;d[i][j]=Long.MAX_VALUE;for(int k=i;k<j;k++)d[i][j]=Math.min(d[i][j],d[i][k]+d[k+1][j]+(long)p[i]*p[k+1]*p[j+1]);}return d[0][n-1];}
 public static int tsp(int[][]g){int n=g.length,all=1<<n;long inf=Long.MAX_VALUE/4;long[][]dp=new long[all][n];for(long[]r:dp)Arrays.fill(r,inf);dp[1][0]=0;for(int mask=1;mask<all;mask++)if((mask&1)!=0)for(int u=0;u<n;u++)if(dp[mask][u]<inf)for(int v=0;v<n;v++)if((mask&(1<<v))==0)dp[mask|1<<v][v]=Math.min(dp[mask|1<<v][v],dp[mask][u]+g[u][v]);long ans=inf;for(int u=1;u<n;u++)ans=Math.min(ans,dp[all-1][u]+g[u][0]);return ans>=inf?-1:(int)ans;}
 public static int knapsack(int[]w,int[]v,int cap){int[]dp=new int[cap+1];for(int i=0;i<w.length;i++)for(int c=cap;c>=w[i];c--)dp[c]=Math.max(dp[c],dp[c-w[i]]+v[i]);return dp[cap];}
}
